#!/usr/bin/env python3
"""Build the RealSense device models in ``roqsim_sensors/models/realsense_<d>/`` from the vendor link.

    python external/convert/build_realsense_devices.py                  # all three
    python external/convert/build_realsense_devices.py realsense_d435   # one
    python external/convert/build_realsense_devices.py --mount-delta    # print each pose delta
    python external/convert/build_realsense_devices.py --rewrite-mounts world.yaml [...]

Writes, per device, the MJCF ``realsense_<d>.xml`` and the generated block of its
``realsense_<d>.manifest.yaml`` (``device_name:``, ``frame_id:`` and ``frames:``, between the two
``generated by`` marker lines; the rest of the manifest is authored by hand, because its numbers come
from data sheets). The meshes are not rebuilt here: they are the converted vendor meshes the models
already ship, each kept 1:1 in the vendor mesh's own axes.

Every number is read from ``realsense2_description`` at a pinned tag of
``IntelRealSense/realsense-ros`` (``_d415.urdf.xacro``, ``_d435.urdf.xacro``, ``_d455.urdf.xacro``,
``_d435i_imu_modules.urdf.xacro``) by evaluating the macro's own ``xacro:property`` expressions, so
nothing is transcribed by hand.

**The MJCF ``mount`` body is ``<name>_link``** (``camera_link``), the link the macro hangs the mesh,
the collision box and every camera frame from. The macro itself attaches ``<name>_bottom_screw_frame``
(the tripod screw) to its parent and ``<name>_link`` to that at a fixed offset, which
``--mount-delta`` prints; a robot port whose description instantiates the macro composes
the two. Inside the mount:

* the visual mesh geom carries the vendor mesh-in-link origin as its pose;
* the front glass plate and the collision box are measured on the converted mesh (mesh-local, in
  :class:`Device`) and carried into the link by that same pose;
* the colour camera sits at the vendor ``<name>_color_optical_frame``: MuJoCo's camera looks down its
  own ``-z`` with ``+y`` up, the ROS optical frame down ``+z`` with ``+y`` down, so its ``xyaxes`` are
  the optical ``x`` and ``-y``.

The manifest's ``frames:`` chain is the vendor's nominal-extrinsics chain for what the device
publishes: colour and depth frames and their optical frames, and for the D435i the gyro frame, its
optical frame and ``<name>_imu_optical_frame`` (co-located with it, as ``_d455.urdf.xacro`` spells
and ``realsense2_camera`` publishes).

**Re-expressing a mount.** The retired ``d415``/``d435``/``d455`` models pre-rotated ``mount`` by
:data:`RETIRED_MOUNT_QUAT` so a mount at ``rpy [0, 0, 0]`` looked along ``+y``, with the mesh in the
body's own axes. A mount of the old model at ``T_old`` put the mesh at ``T_old * Rq``; the new model
puts it at ``T_new * T_link_mesh``, so ``T_new = T_old * D`` with ``D = Rq * T_link_mesh^-1``.
``--rewrite-mounts`` applies ``D`` to every ``spawn_sensor`` of a retired model in the YAML files it
is given, renames the model, and leaves every other line as written (``vendor_mount.py``).
"""

from __future__ import annotations

import argparse
import sys
from dataclasses import dataclass
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parent))
from sources import resolve_source  # noqa: E402
from vendor_mount import (  # noqa: E402
    Xacro,
    fmt_list,
    fmt_num,
    fmt_vec,
    matrix_quat,
    matrix_rpy,
    quat_matrix,
    rewrite_mounts,
    rpy_matrix,
    splice,
)

ROOT = Path(__file__).resolve().parents[2]
MODELS = ROOT / "roqsim_sensors/src/roqsim_sensors/models"

REALSENSE_URL = "https://github.com/IntelRealSense/realsense-ros.git"
#: Tag 4.56.1.
REALSENSE_COMMIT = "53169f3265266d07e88c025b950aa4ccaa03e671"
REALSENSE_SPARSE = "realsense2_description"

#: The retired models' ``mount`` quaternion (w, x, y, z): mesh +z -> +y, mesh +y -> +z.
RETIRED_MOUNT_QUAT = (0.0, 0.0, 0.70710678, 0.70710678)

BEGIN = "# --- generated by external/convert/build_realsense_devices.py from realsense2_description"
END = "# --- end of generated block"


@dataclass(frozen=True)
class Device:
    name: str  # the model name, realsense_<d>
    retired: str  # the model name it replaces
    xacro: str  # file under realsense2_description/urdf/
    prefix: str  # the xacro property prefix, d435_
    mesh: str  # the converted mesh the model ships
    #: Geoms measured on the converted mesh, in its own axes: (name, pos, size) boxes.
    front: tuple[tuple[float, float, float], tuple[float, float, float]] | None
    collision: tuple[tuple[float, float, float], tuple[float, float, float]]
    fovy: float
    resolution: tuple[int, int]
    #: The D435i's inertial module, whose frames the manifest's `imu` component stamps.
    imu_xacro: str | None = None


DEVICES = {
    d.name: d
    for d in (
        Device(
            name="realsense_d415",
            retired="d415",
            xacro="_d415.urdf.xacro",
            prefix="d415_",
            mesh="d415.obj",
            front=None,
            collision=((0.0, 0.0, -0.01), (0.0495, 0.0115, 0.01)),
            fovy=42.5,
            resolution=(640, 480),
        ),
        Device(
            name="realsense_d435",
            retired="d435",
            xacro="_d435.urdf.xacro",
            prefix="d435_",
            mesh="d435.obj",
            front=((0.0, 0.0, 0.0004), (0.038, 0.0085, 0.0004)),
            collision=((0.0, 0.0, -0.01285), (0.04536, 0.01314, 0.01286)),
            fovy=42.5,
            resolution=(640, 480),
            imu_xacro="_d435i_imu_modules.urdf.xacro",
        ),
        Device(
            name="realsense_d455",
            retired="d455",
            xacro="_d455.urdf.xacro",
            prefix="d455_",
            mesh="d455.obj",
            front=((0.0, 0.0, 0.0003), (0.055, 0.0105, 0.0004)),
            collision=((0.0, 0.0, -0.0131), (0.062, 0.0145, 0.013)),
            fovy=62.0,
            resolution=(640, 400),
        ),
    )
}

RETIRED = {d.retired: d for d in DEVICES.values()}


# -- the vendor description ------------------------------------------------------------------------


def _source() -> Path:
    return resolve_source(
        "realsense-ros",
        REALSENSE_URL,
        REALSENSE_COMMIT,
        sparse=REALSENSE_SPARSE,
        subdir=f"{REALSENSE_SPARSE}/urdf",
    )


@dataclass(frozen=True)
class Vendor:
    """What the model is built from, all in ``<name>_link``."""

    mesh_xyz: tuple[float, ...]
    mesh_rpy: tuple[float, ...]
    screw_to_link: tuple[float, ...]
    color: tuple[float, ...]
    depth: tuple[float, ...]
    optical_rpy: tuple[float, ...]
    imu: tuple[float, ...] | None

    @property
    def link_mesh(self) -> tuple[np.ndarray, np.ndarray]:
        return rpy_matrix(self.mesh_rpy), np.asarray(self.mesh_xyz, dtype=float)


def vendor(device: Device, urdf: Path | None = None) -> Vendor:
    urdf = urdf or _source()
    x = Xacro(urdf / device.xacro, "camera")
    mesh_xyz, mesh_rpy = x.mesh_origin()
    screw, _, _ = x.joint("link_joint")
    color, color_rpy, _ = x.joint("color_joint")
    depth, depth_rpy, _ = x.joint("depth_joint")
    _, optical, _ = x.joint("color_optical_joint")
    _, depth_optical, _ = x.joint("depth_optical_joint")
    if any(color_rpy) or any(depth_rpy) or not np.allclose(optical, depth_optical):
        raise RuntimeError(
            f"{device.xacro}: colour/depth frames are not the plain chain assumed here"
        )
    imu = None
    if device.imu_xacro:
        m = Xacro(urdf / device.imu_xacro, "camera")
        accel, accel_rpy, _ = m.joint("accel_joint")
        imu, imu_rpy, _ = m.joint("gyro_joint")
        _, gyro_optical, _ = m.joint("gyro_optical_joint")
        if accel != imu or any(accel_rpy) or any(imu_rpy) or not np.allclose(gyro_optical, optical):
            raise RuntimeError(f"{device.imu_xacro}: accel and gyro are not co-located as assumed")
    return Vendor(mesh_xyz, mesh_rpy, screw, color, depth, optical, imu)


def mount_delta(device: Device, v: Vendor) -> tuple[np.ndarray, np.ndarray]:
    """``D = Rq * T_link_mesh^-1`` as (rotation, translation): ``T_new = T_old * D``."""
    r_lm, t_lm = v.link_mesh
    r = quat_matrix(RETIRED_MOUNT_QUAT) @ r_lm.T
    return r, -r @ t_lm


# -- output ----------------------------------------------------------------------------------------


def mjcf(device: Device, v: Vendor) -> str:
    r_lm, t_lm = v.link_mesh
    q_lm = matrix_quat(r_lm)

    def placed(pos) -> np.ndarray:
        return r_lm @ np.asarray(pos, dtype=float) + t_lm

    short = device.retired
    r_opt = rpy_matrix(v.optical_rpy)  # color_frame <- color_optical_frame
    cam_x, cam_y = r_opt[:, 0], -r_opt[:, 1]
    front = ""
    if device.front:
        pos, size = device.front
        front = f"""
      <!-- Front glass strip: the decimated mesh has no separate material for the front window, so
           a thin black plate stands in, just proud of the mesh's front face. -->
      <geom name="{short}_front" type="box" pos="{fmt_vec(placed(pos))}" quat="{fmt_vec(q_lm)}"
            size="{fmt_vec(size)}" material="{short}_glass" contype="0" conaffinity="0"/>"""
    glass = (
        f'\n    <material name="{short}_glass" rgba="0.05 0.05 0.05 1" specular="0.6" '
        f'shininess="0.6"/>'
        if device.front
        else ""
    )
    cpos, csize = device.collision
    return f"""<mujoco model="{device.name}">
  <!--
    Intel RealSense {short.upper()}: visual mesh + a colour camera, mounted by `spawn_sensor` at the
    vendor joint origin of `<name>_link`. Written by external/convert/build_realsense_devices.py from
    realsense2_description/urdf/{device.xacro} @ realsense-ros {REALSENSE_COMMIT[:7]} (tag 4.56.1);
    see {device.name.upper()}_MESH_LICENSE.

    The `mount` body IS `camera_link`: x forward (the lens normal), y left, z up. The mesh keeps
    its own axes and carries the vendor mesh-in-link origin as its pose; the front plate and the
    collision box were measured on the converted mesh and ride the same pose. `{short}_color` is
    the vendor `camera_color_optical_frame`, turned into MuJoCo's camera convention (looks down -z,
    +y up). The manifest's `frames:` publishes the vendor chain from this body.
  -->
  <compiler angle="radian" meshdir="meshes" autolimits="true"/>

  <asset>
    <mesh name="{short}_mesh" file="{device.mesh}"/>
    <material name="{short}_body" rgba="0.75 0.75 0.77 1" specular="0.4" shininess="0.3"/>{glass}
  </asset>

  <worldbody>
    <body name="mount">
      <geom name="{short}_visual" type="mesh" mesh="{short}_mesh" material="{short}_body"
            pos="{fmt_vec(t_lm)}" quat="{fmt_vec(q_lm)}" contype="0" conaffinity="0"/>{front}
      <geom name="{short}_collision" type="box" pos="{fmt_vec(placed(cpos))}" quat="{fmt_vec(q_lm)}"
            size="{fmt_vec(csize)}" group="3"/>
      <camera name="{short}_color" pos="{fmt_vec(v.color)}" xyaxes="{fmt_vec(cam_x)} {fmt_vec(cam_y)}"
              fovy="{fmt_num(device.fovy)}" resolution="{device.resolution[0]} {device.resolution[1]}"/>
    </body>
  </worldbody>
</mujoco>
"""


def frames_block(device: Device, v: Vendor) -> str:
    opt = fmt_list(v.optical_rpy)
    lines = [
        BEGIN,
        f"# (urdf/{device.xacro}, nominal extrinsics). The macro's `name` param is the device name.",
        "device_name: camera",
        'frame_id: "{device_name}_color_optical_frame"',
        "frames:",
        '  - {name: "{device_name}_link", parent: mount}',
        f'  - {{name: "{{device_name}}_color_frame", parent: "{{device_name}}_link", '
        f"pos: {fmt_list(v.color)}}}",
        f'  - {{name: "{{frame_id}}", parent: "{{device_name}}_color_frame", rpy: {opt}}}',
        f'  - {{name: "{{device_name}}_depth_frame", parent: "{{device_name}}_link", '
        f"pos: {fmt_list(v.depth)}}}",
        f'  - {{name: "{{device_name}}_depth_optical_frame", parent: "{{device_name}}_depth_frame", '
        f"rpy: {opt}}}",
    ]
    if v.imu is not None:
        lines += [
            f'  - {{name: "{{device_name}}_gyro_frame", parent: "{{device_name}}_link", '
            f"pos: {fmt_list(v.imu)}}}",
            f'  - {{name: "{{device_name}}_gyro_optical_frame", parent: "{{device_name}}_gyro_frame", '
            f"rpy: {opt}}}",
            '  - {name: "{device_name}_imu_optical_frame", parent: "{device_name}_gyro_optical_frame"}',
        ]
    lines.append(END)
    return "\n".join(lines) + "\n"


def build(device: Device, urdf: Path) -> None:
    v = vendor(device, urdf)
    folder = MODELS / device.name
    (folder / f"{device.name}.xml").write_text(mjcf(device, v))
    splice(folder / f"{device.name}.manifest.yaml", frames_block(device, v), BEGIN, END)
    print(f"{device.name}: wrote {device.name}.xml and the manifest's frames block")


def main(argv: list[str] | None = None) -> None:
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("devices", nargs="*", help=f"any of {sorted(DEVICES)}; default: all")
    ap.add_argument("--mount-delta", action="store_true", help="print each retired model's delta")
    ap.add_argument("--rewrite-mounts", nargs="+", type=Path, metavar="YAML")
    args = ap.parse_args(argv)
    urdf = _source()
    deltas = {d.retired: (d.name, mount_delta(d, vendor(d, urdf))) for d in DEVICES.values()}
    if args.mount_delta:
        for old, (new, (r, t)) in deltas.items():
            screw = vendor(DEVICES[new], urdf).screw_to_link
            print(
                f"{old} -> {new}: T_new = T_old * D, D.pos = {fmt_list(t)}, "
                f"D.rpy = {fmt_list(matrix_rpy(r))}; bottom_screw_frame -> camera_link {fmt_list(screw)}"
            )
        return
    if args.rewrite_mounts:
        for path in args.rewrite_mounts:
            print(f"{path}: {rewrite_mounts(path, deltas)} mount(s) re-expressed")
        return
    unknown = sorted(set(args.devices) - set(DEVICES))
    if unknown:
        ap.error(f"unknown device(s) {unknown}; known: {sorted(DEVICES)}")
    for name in args.devices or DEVICES:
        build(DEVICES[name], urdf)


if __name__ == "__main__":
    main()
